import React from "react";
import {DesktopDatePicker, LocalizationProvider} from '@mui/x-date-pickers';
import {AdapterDateFns} from "@mui/x-date-pickers/AdapterDateFnsV3";
import {isSameDay, isSameMonth, isSameYear} from "date-fns";

// How finely a frequency's dates are compared: annual by year, sub-annual by month, else by day
export const sameTimeFor = frequency => {
    if (['a'].includes(frequency)) return isSameYear;
    if (['sa', 'q', 'm'].includes(frequency)) return isSameMonth;
    return isSameDay;
}

const DatePicker = ({
                        date,
                        label,
                        minDate,
                        maxDate,
                        title,
                        updateDate,
                        isDisabled,
                        frequency,
                        shouldDisableSelections = (_isSameTime) => (_t) => false
                    }) => {

    const handleDateChange = newValue => {
        updateDate({target: {value: newValue}});
    };

    const availableViews = ['day', 'month', 'year'];
    let minimumView = 'day'

    if (['a'].includes(frequency)) {
        availableViews.splice(0, 2)
        minimumView = availableViews[0]
    } else if (['sa', 'q', 'm'].includes(frequency)) {
        availableViews.splice(0, 1)
        minimumView = availableViews[0]
    }

    const dateSelectionFunc = sameTimeFor(frequency)

    const shouldDisableFunc = shouldDisableSelections(dateSelectionFunc)

    return (
        <div>
            <LocalizationProvider dateAdapter={AdapterDateFns}>
                <DesktopDatePicker
                    label={label}
                    value={date}
                    minDate={minDate}
                    maxDate={maxDate}
                    shouldDisableDate={minimumView === 'day' ? shouldDisableFunc : undefined}
                    shouldDisableMonth={minimumView === 'month' ? shouldDisableFunc : undefined}
                    shouldDisableYear={minimumView === 'year' ? shouldDisableFunc : undefined}
                    views={availableViews}
                    onChange={handleDateChange}
                    disabled={isDisabled}
                    slotProps={{textField: {fullWidth: true, title}}}
                />
            </LocalizationProvider>
        </div>
    );
}

export default DatePicker;